-- Content-only, guarded, 10 tasks: automation-engineering
BEGIN;
CREATE TEMP TABLE legacy_guides(payload jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO legacy_guides(payload) VALUES ($legacy_payload$[{"slug":"automation-engineering","task_number":1,"title":"Process Mapping","old_description":"[[AZ]]\nƏl ilə görülən təcrübə müraciəti prosesini xəritələ və avtomatlaşdırma sərhədlərini müəyyən et.\n\n[[EN]]\nMap a manual internship-application process and define what should be automated.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nTəcrübə müraciətinin əl ilə yoxlanma prosesini diaqramda göstərəcək və hansı addımların avtomatlaşdırıla biləcəyini müəyyən edəcəksən.\n\n## 2. Başlamazdan əvvəl\nFlowchart/proses diaqramının əsasları və diagrams.net və ya Mermaid kimi alətdən istifadə. Uydurma müraciət nümunələri işlət.\n\n## 3. Addım-addım icra\n1. GitHub-da özünə boş `internship-process-map` repo-su yarat. İlk tapşırıqdır: sıfırdan başla.\n2. `README.md`, `process.md` və diaqram faylı yarat.\n3. Bu axını göstər: tələbə formu göndərir → koordinator yoxlayır → natamam forma geri qaytarılır → uyğun müraciət rəhbərə ötürülür.\n4. Hər mərhələdə məsul şəxsi, qərarı və növbəti addımı göstər.\n5. Ən azı 5 istisna əlavə et: boş sahə, səhv e-poçt, təkrar müraciət, uyğun olmayan namizəd və sistem xətası.\n6. Hər addımı “avtomatlaşdırıla bilər”, “insan təsdiqi lazımdır” və ya “əl ilə qalmalıdır” kimi işarələ və səbəbini yaz.\n7. README-də diaqramın necə açıldığını izah et və faylları GitHub-a göndər.\n\n## 4. Konkret nümunə və izah\nDiaqramda düzbucaqlı addımı, romb qərarı göstərsin: “Form doludur?” → bəli: yoxlamaya göndər; xeyr: çatışmayan sahələri bildir. Bu tapşırıq üçün proqram yazmaq tələb olunmur.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, proses diaqramı, ən azı 5 istisna ssenarisi və avtomatlaşdırma qərarlarının izahı.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nBaşlanğıc, uğurlu son və 5 istisnanın sonu görünür. Hər qərarın çıxışları və məsul şəxsi yazılıb; diaqram başqa şəxs tərəfindən açıla bilir.\n\n[[EN]]\n## 1. Goal\nMap the manual internship-application review process and identify which steps could be automated.\n\n## 2. Before you start\nBasic flowchart concepts and a tool such as diagrams.net or Mermaid. Use fictional application examples.\n\n## 3. Step-by-step work\n1. Create your own empty GitHub repository named `internship-process-map`. This is the first task: start from scratch.\n2. Create `README.md`, `process.md`, and a diagram file.\n3. Map this flow: student submits a form → coordinator checks it → incomplete forms are returned → eligible applications go to a reviewer.\n4. Show the owner, decision, and next step at each stage.\n5. Add at least five exceptions: missing field, invalid email, duplicate application, ineligible candidate, and system error.\n6. Label each step “can be automated,” “human approval needed,” or “keep manual,” and explain why.\n7. Explain how to view the diagram in README and push the files to GitHub.\n\n## 4. Concrete example and explanation\nUse rectangles for actions and diamonds for decisions: “Is the form complete?” → yes: review; no: report missing fields. No application code is required for this task.\n\n## 5. What to submit\nYour own GitHub repository link, process diagram, at least five exception scenarios, and explanations of automation decisions.\n\n## 6. How to check your work\nShow a start, successful end, and outcomes for five exceptions. Label each decision branch and owner; ensure another person can open the diagram.","new_description":"[[AZ]]\nƏl ilə görülən təcrübə müraciəti prosesini xəritələ və avtomatlaşdırma sərhədlərini müəyyən et.\n\nPulsuz alətlər: diagrams.net, Google Docs (personal). Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nMap a manual internship-application process and define what should be automated.\n\nFree tools: diagrams.net, Google Docs (personal). See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** Müraciət forması → admin yoxlama → status → bildiriş axınında hansı addımların əl işi olduğunu göstər.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **diagrams.net** — https://app.diagrams.net. Blank diagram seç, addımları oxlarla birləşdir və PNG/PDF çıxart.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / automation-engineering / task-1` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. Əvvəlki prosesin ən azı 6 addımını swimlane/diaqramda çək. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. İnsan təsdiqi və avtomatlaşdırıla bilən addımları fərqli işarələ. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. Yalnız bir addımın avtomatlaşmasının vaxt və risk təsirini izah et. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: Müraciət forması → admin yoxlama → status → bildiriş axınında hansı addımların əl işi olduğunu göstər. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\nMüraciət forması → admin yoxlama → status → bildiriş axınında hansı addımların əl işi olduğunu göstər.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nTəcrübə müraciətinin əl ilə yoxlanma prosesini diaqramda göstərəcək və hansı addımların avtomatlaşdırıla biləcəyini müəyyən edəcəksən.\n\n## 2. Başlamazdan əvvəl\nFlowchart/proses diaqramının əsasları və diagrams.net və ya Mermaid kimi alətdən istifadə. Uydurma müraciət nümunələri işlət.\n\n## 3. Addım-addım icra\n1. GitHub-da özünə boş `internship-process-map` repo-su yarat. İlk tapşırıqdır: sıfırdan başla.\n2. `README.md`, `process.md` və diaqram faylı yarat.\n3. Bu axını göstər: tələbə formu göndərir → koordinator yoxlayır → natamam forma geri qaytarılır → uyğun müraciət rəhbərə ötürülür.\n4. Hər mərhələdə məsul şəxsi, qərarı və növbəti addımı göstər.\n5. Ən azı 5 istisna əlavə et: boş sahə, səhv e-poçt, təkrar müraciət, uyğun olmayan namizəd və sistem xətası.\n6. Hər addımı “avtomatlaşdırıla bilər”, “insan təsdiqi lazımdır” və ya “əl ilə qalmalıdır” kimi işarələ və səbəbini yaz.\n7. README-də diaqramın necə açıldığını izah et və faylları GitHub-a göndər.\n\n## 4. Konkret nümunə və izah\nDiaqramda düzbucaqlı addımı, romb qərarı göstərsin: “Form doludur?” → bəli: yoxlamaya göndər; xeyr: çatışmayan sahələri bildir. Bu tapşırıq üçün proqram yazmaq tələb olunmur.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, proses diaqramı, ən azı 5 istisna ssenarisi və avtomatlaşdırma qərarlarının izahı.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nBaşlanğıc, uğurlu son və 5 istisnanın sonu görünür. Hər qərarın çıxışları və məsul şəxsi yazılıb; diaqram başqa şəxs tərəfindən açıla bilir.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** Map a fictional application form → admin review → status update → notification flow.\n\n## Free tools and platforms\n- **diagrams.net** — https://app.diagrams.net. Create a blank diagram, connect steps with arrows and export PNG/PDF.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / automation-engineering / task-1` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Draw at least six steps in a current-state workflow. Show evidence in a file, local demo or measurable test.\n4. Distinguish human approvals from safe automation opportunities. Show evidence in a file, local demo or measurable test.\n5. Explain the time/risk impact of automating one step. Show evidence in a file, local demo or measurable test.\n6. Verify this example: Map a fictional application form → admin review → status update → notification flow. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nMap a fictional application form → admin review → status update → notification flow.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nMap the manual internship-application review process and identify which steps could be automated.\n\n## 2. Before you start\nBasic flowchart concepts and a tool such as diagrams.net or Mermaid. Use fictional application examples.\n\n## 3. Step-by-step work\n1. Create your own empty GitHub repository named `internship-process-map`. This is the first task: start from scratch.\n2. Create `README.md`, `process.md`, and a diagram file.\n3. Map this flow: student submits a form → coordinator checks it → incomplete forms are returned → eligible applications go to a reviewer.\n4. Show the owner, decision, and next step at each stage.\n5. Add at least five exceptions: missing field, invalid email, duplicate application, ineligible candidate, and system error.\n6. Label each step “can be automated,” “human approval needed,” or “keep manual,” and explain why.\n7. Explain how to view the diagram in README and push the files to GitHub.\n\n## 4. Concrete example and explanation\nUse rectangles for actions and diamonds for decisions: “Is the form complete?” → yes: review; no: report missing fields. No application code is required for this task.\n\n## 5. What to submit\nYour own GitHub repository link, process diagram, at least five exception scenarios, and explanations of automation decisions.\n\n## 6. How to check your work\nShow a start, successful end, and outcomes for five exceptions. Label each decision branch and owner; ensure another person can open the diagram."},{"slug":"automation-engineering","task_number":2,"title":"Webhook to Workflow","old_description":"[[AZ]]\nWebhook qəbul edib yoxlanılan məlumatı idarə olunan workflow-a ötür.\n\n[[EN]]\nReceive a webhook and pass validated data into a controlled workflow.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nWebhook gələndə sadə workflow başladan avtomatlaşdırma quracaqsan.\n\n## 2. Başlamazdan əvvəl\nTapşırıq 1-dəki öz workflow xəritən, JSON, HTTP request və webhook anlayışları. Ödənişli servis yoxdursa, lokal webhook/mock endpoint istifadə et.\n\n## 3. Addım-addım icra\n1. Öz automation repo-nu və ya workflow faylını davam etdir.\n2. Sintetik event JSON-u müəyyən et.\n3. Webhook qəbul edən lokal endpoint və ya mock trigger qur.\n4. Input-u yoxla, sonra workflow-da iki sadə addım icra et.\n5. Invalid JSON və təkrar event hallarını test et.\n6. Trigger → action axınını diaqram və README ilə izah et.\n\n## 4. Konkret nümunə və izah\nWebhook başqa sistemin HTTP sorğusu ilə iş axınını başlatmasıdır. Lokal `POST /events` üçün `{\"event_id\":\"demo-1\",\"type\":\"application_created\"}` göndər; məlumatı yoxla, sonra qeydi saxla və simulyasiya edilmiş bildiriş yarat.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin və ya export edilən workflow, nümunə event, test nəticələri və axın diaqramı. Secret və real şəxsi məlumat işlətmə.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nDüzgün event iki addımı tamamlayır, səhv JSON rədd olunur və eyni event_id ikinci dəfə nəticə yaratmır. Sorğunu necə göndərmək README-də göstərilib.\n\n[[EN]]\n## 1. Goal\nBuild an automation workflow that starts when a webhook event arrives.\n\n## 2. Before you start\nYour workflow map from Task 1, JSON, HTTP requests, and webhooks. Use a local webhook/mock endpoint if no paid service is available.\n\n## 3. Step-by-step work\n1. Continue your own automation repository or workflow file.\n2. Define a synthetic event JSON.\n3. Set up a local endpoint or mock trigger to receive the webhook.\n4. Validate the input, then perform two simple workflow actions.\n5. Test invalid JSON and duplicate events.\n6. Explain the trigger-to-action flow with a diagram and README.\n\n## 4. Concrete example and explanation\nA webhook starts a workflow when another system sends an HTTP request. Send `{\"event_id\":\"demo-1\",\"type\":\"application_created\"}` to local `POST /events`; validate, store a record, then create a simulated notification.\n\n## 5. What to submit\nYour own GitHub repository or exported workflow, sample event, test results, and flow diagram. Do not use secrets or real personal data.\n\n## 6. How to check your work\nA valid event completes both actions; invalid JSON is rejected; repeating the same event_id creates no duplicate output. Document a reproducible request.","new_description":"[[AZ]]\nWebhook qəbul edib yoxlanılan məlumatı idarə olunan workflow-a ötür.\n\nPulsuz alətlər: Python (free), FastAPI (open source), curl. Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nReceive a webhook and pass validated data into a controlled workflow.\n\nFree tools: Python (free), FastAPI (open source), curl. See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** Lokal `POST /webhook` göndərişi `{'event':'application.created','id':'demo-01'}` qəbul etsin.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Python layihəsində lokal HTTP endpoint və Pydantic input modeli yarat; ödənişli server lazım deyil.\n- **curl** — https://curl.se. Yalnız öz lokal HTTP servisindən test sorğuları göndər, status və JSON cavablarını yoxla.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / automation-engineering / task-2` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. FastAPI-də lokal webhook route və Pydantic schema yarat. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. `curl` ilə düzgün/yanlış payload-lar göndər, nəticəni logla. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. Eyni event iki dəfə gəldikdə idempotency açarı ilə duplicate nəticəni göstər. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: Lokal `POST /webhook` göndərişi `{'event':'application.created','id':'demo-01'}` qəbul etsin. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\nLokal `POST /webhook` göndərişi `{'event':'application.created','id':'demo-01'}` qəbul etsin.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nWebhook gələndə sadə workflow başladan avtomatlaşdırma quracaqsan.\n\n## 2. Başlamazdan əvvəl\nTapşırıq 1-dəki öz workflow xəritən, JSON, HTTP request və webhook anlayışları. Ödənişli servis yoxdursa, lokal webhook/mock endpoint istifadə et.\n\n## 3. Addım-addım icra\n1. Öz automation repo-nu və ya workflow faylını davam etdir.\n2. Sintetik event JSON-u müəyyən et.\n3. Webhook qəbul edən lokal endpoint və ya mock trigger qur.\n4. Input-u yoxla, sonra workflow-da iki sadə addım icra et.\n5. Invalid JSON və təkrar event hallarını test et.\n6. Trigger → action axınını diaqram və README ilə izah et.\n\n## 4. Konkret nümunə və izah\nWebhook başqa sistemin HTTP sorğusu ilə iş axınını başlatmasıdır. Lokal `POST /events` üçün `{\"event_id\":\"demo-1\",\"type\":\"application_created\"}` göndər; məlumatı yoxla, sonra qeydi saxla və simulyasiya edilmiş bildiriş yarat.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin və ya export edilən workflow, nümunə event, test nəticələri və axın diaqramı. Secret və real şəxsi məlumat işlətmə.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nDüzgün event iki addımı tamamlayır, səhv JSON rədd olunur və eyni event_id ikinci dəfə nəticə yaratmır. Sorğunu necə göndərmək README-də göstərilib.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** Build a local POST /webhook endpoint accepting a fictional application-created JSON event.\n\n## Free tools and platforms\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Create local Python HTTP endpoints with Pydantic validation; paid hosting is unnecessary.\n- **curl** — https://curl.se. Send test requests only to authorized local endpoints and check status/JSON results.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / automation-engineering / task-2` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Create a localhost webhook route with Pydantic validation. Show evidence in a file, local demo or measurable test.\n4. Send valid and invalid JSON with curl and inspect responses. Show evidence in a file, local demo or measurable test.\n5. Demonstrate duplicate-event handling using an idempotency key. Show evidence in a file, local demo or measurable test.\n6. Verify this example: Build a local POST /webhook endpoint accepting a fictional application-created JSON event. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nBuild a local POST /webhook endpoint accepting a fictional application-created JSON event.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nBuild an automation workflow that starts when a webhook event arrives.\n\n## 2. Before you start\nYour workflow map from Task 1, JSON, HTTP requests, and webhooks. Use a local webhook/mock endpoint if no paid service is available.\n\n## 3. Step-by-step work\n1. Continue your own automation repository or workflow file.\n2. Define a synthetic event JSON.\n3. Set up a local endpoint or mock trigger to receive the webhook.\n4. Validate the input, then perform two simple workflow actions.\n5. Test invalid JSON and duplicate events.\n6. Explain the trigger-to-action flow with a diagram and README.\n\n## 4. Concrete example and explanation\nA webhook starts a workflow when another system sends an HTTP request. Send `{\"event_id\":\"demo-1\",\"type\":\"application_created\"}` to local `POST /events`; validate, store a record, then create a simulated notification.\n\n## 5. What to submit\nYour own GitHub repository or exported workflow, sample event, test results, and flow diagram. Do not use secrets or real personal data.\n\n## 6. How to check your work\nA valid event completes both actions; invalid JSON is rejected; repeating the same event_id creates no duplicate output. Document a reproducible request."},{"slug":"automation-engineering","task_number":3,"title":"Retries and Monitoring","old_description":"[[AZ]]\nUğursuz addımları idempotent retry, gecikmə və monitorinq ilə bərpa et.\n\n[[EN]]\nRecover failed workflow steps with idempotent retries, backoff, and monitoring.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nWorkflow-da müvəqqəti xətaları idarə edəcək, retry və monitorinq əlavə edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz webhook workflow-n, error handling, retry və log anlayışları.\n\n## 3. Addım-addım icra\n1. Öz automation layihəni davam etdir.\n2. Uğurlu cavab, timeout və müvəqqəti server xətası üçün mock addım yarat.\n3. Məhdud retry sayı və artan gözləmə müddəti təyin et.\n4. Daimi validation xətasında sonsuz retry etmə.\n5. Hər icra üçün run ID, status və müddət qeyd et; secret və payload-da şəxsi məlumat loglama.\n6. Uğurlu, uğursuz və retry ssenarilərini test et.\n\n## 4. Konkret nümunə və izah\nTəkrar cəhd (retry) müvəqqəti xəta üçün yenidən sorğu göndərməkdir. Məsələn, ilk iki cəhd 503, üçüncü 200 qaytarsın; gözləmə 1 və 2 saniyə olsun. 400 format xətasında təkrar cəhd etmə.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin/workflow export-u, retry qaydası, log nümunələri və ən azı 3 ssenarinin test nəticəsi. Workflow sonsuz təkrar etməməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nMaksimum cəhd sayı və gözləmə qaydası yazılıb. Log eyni run ID altında bütün cəhdləri göstərir; həmişə uğursuz xidmət sonsuz dövr yaratmır.\n\n[[EN]]\n## 1. Goal\nHandle temporary workflow failures with retry logic and monitoring.\n\n## 2. Before you start\nYour webhook workflow, error handling, retries, and logging.\n\n## 3. Step-by-step work\n1. Continue your own automation project.\n2. Mock success, timeout, and temporary server-error steps.\n3. Set a limited retry count and increasing delay.\n4. Do not retry permanent validation errors forever.\n5. Record run ID, status, and duration; never log secrets or personal payload data.\n6. Test success, failure, and retry scenarios.\n\n## 4. Concrete example and explanation\nA retry repeats a request after a temporary failure. Simulate 503 twice, then 200, with waits of one and two seconds. Do not retry a 400 validation failure.\n\n## 5. What to submit\nYour own GitHub repository/workflow export, retry rules, log examples, and results for at least three scenarios. The workflow must never retry indefinitely.\n\n## 6. How to check your work\nDocument retry limits and delays. Logs group attempts under one run ID; a permanently failing service cannot create an endless loop.","new_description":"[[AZ]]\nUğursuz addımları idempotent retry, gecikmə və monitorinq ilə bərpa et.\n\nPulsuz alətlər: Python (free), Visual Studio Code. Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nRecover failed workflow steps with idempotent retries, backoff, and monitoring.\n\nFree tools: Python (free), Visual Studio Code. See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** Lokal workflow müvəqqəti 503 xətası versin; maksimum 3 cəhd və 1s/2s/4s backoff-u simulyasiya et.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / automation-engineering / task-3` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. Müvəqqəti və daimi xətaları fərqli klassifikasiya et. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. Maksimum 3 cəhd və backoff üçün test edilə bilən funksiya qur. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. Təkrar icra eyni nəticəni ikinci dəfə yazmamalıdır; loglarla sübut et. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: Lokal workflow müvəqqəti 503 xətası versin; maksimum 3 cəhd və 1s/2s/4s backoff-u simulyasiya et. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\nLokal workflow müvəqqəti 503 xətası versin; maksimum 3 cəhd və 1s/2s/4s backoff-u simulyasiya et.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nWorkflow-da müvəqqəti xətaları idarə edəcək, retry və monitorinq əlavə edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz webhook workflow-n, error handling, retry və log anlayışları.\n\n## 3. Addım-addım icra\n1. Öz automation layihəni davam etdir.\n2. Uğurlu cavab, timeout və müvəqqəti server xətası üçün mock addım yarat.\n3. Məhdud retry sayı və artan gözləmə müddəti təyin et.\n4. Daimi validation xətasında sonsuz retry etmə.\n5. Hər icra üçün run ID, status və müddət qeyd et; secret və payload-da şəxsi məlumat loglama.\n6. Uğurlu, uğursuz və retry ssenarilərini test et.\n\n## 4. Konkret nümunə və izah\nTəkrar cəhd (retry) müvəqqəti xəta üçün yenidən sorğu göndərməkdir. Məsələn, ilk iki cəhd 503, üçüncü 200 qaytarsın; gözləmə 1 və 2 saniyə olsun. 400 format xətasında təkrar cəhd etmə.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin/workflow export-u, retry qaydası, log nümunələri və ən azı 3 ssenarinin test nəticəsi. Workflow sonsuz təkrar etməməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nMaksimum cəhd sayı və gözləmə qaydası yazılıb. Log eyni run ID altında bütün cəhdləri göstərir; həmişə uğursuz xidmət sonsuz dövr yaratmır.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** Simulate a local workflow returning temporary 503 errors with bounded exponential retry.\n\n## Free tools and platforms\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / automation-engineering / task-3` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Separate transient failures from permanent errors. Show evidence in a file, local demo or measurable test.\n4. Implement bounded retries and delays in a testable function. Show evidence in a file, local demo or measurable test.\n5. Verify retries do not create duplicate results and record outcomes. Show evidence in a file, local demo or measurable test.\n6. Verify this example: Simulate a local workflow returning temporary 503 errors with bounded exponential retry. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nSimulate a local workflow returning temporary 503 errors with bounded exponential retry.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nHandle temporary workflow failures with retry logic and monitoring.\n\n## 2. Before you start\nYour webhook workflow, error handling, retries, and logging.\n\n## 3. Step-by-step work\n1. Continue your own automation project.\n2. Mock success, timeout, and temporary server-error steps.\n3. Set a limited retry count and increasing delay.\n4. Do not retry permanent validation errors forever.\n5. Record run ID, status, and duration; never log secrets or personal payload data.\n6. Test success, failure, and retry scenarios.\n\n## 4. Concrete example and explanation\nA retry repeats a request after a temporary failure. Simulate 503 twice, then 200, with waits of one and two seconds. Do not retry a 400 validation failure.\n\n## 5. What to submit\nYour own GitHub repository/workflow export, retry rules, log examples, and results for at least three scenarios. The workflow must never retry indefinitely.\n\n## 6. How to check your work\nDocument retry limits and delays. Logs group attempts under one run ID; a permanently failing service cannot create an endless loop."},{"slug":"automation-engineering","task_number":4,"title":"Integrated Automation Case Study","old_description":"[[AZ]]\nAvtomatlaşdırma üçün biznes axınını başdan sona qur, risk və human-in-the-loop nöqtələrini göstər.\n\n[[EN]]\nBuild an end-to-end business workflow and identify risk and human-approval points.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nBir biznes prosesini başlanğıcdan sona qədər avtomatlaşdırıb nəticəni ölçülə bilən case study kimi təqdim edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz Tapşırıq 1–3 workflow-ların, data transformation, retry və log əsasları. Ödənişli inteqrasiya tələb olunmur; mock alternativ qəbul edilir.\n\n## 3. Addım-addım icra\n1. Əvvəlki automation işlərini öz repo/workflow faylında birləşdir.\n2. Trigger, input, əsas addımlar, error path və output-u təsvir et.\n3. Input validation, retry limit və duplicate event qoruması əlavə et.\n4. Ən azı 5 sintetik event ilə workflow-u test et.\n5. Müddət, uğur faizi və manual addımların azalması kimi ölçüləri hesabla; təxminləri ayrıca qeyd et.\n6. Quraşdırma, məhdudiyyətlər və növbəti addımları yaz.\n\n## 4. Konkret nümunə və izah\nMüraciət event-i → sahələri yoxla → bir qeydi saxla → bildiriş yarat. Beş event-dən biri səhv, biri təkrar olsun. Bu inteqrasiya mərhələsidir; yekun texniki təhvil 10-cu tapşırıqda hazırlanır.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin/workflow export-u, diaqram, test nəticələri, ölçülər və case-study hesabatı. Uğur rəqəmləri real ölçü və ya təxmin kimi açıq işarələnməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nNormal, səhv, təkrar və müvəqqəti xəta yollarının nəticəsi göstərilib. Uğur faizi = uğurlu icra / bütün unikal icralar × 100; hansı icraların sayıldığı yazılıb.\n\n[[EN]]\n## 1. Goal\nAutomate a business process end to end and present the result as a measurable case study.\n\n## 2. Before you start\nYour workflows from Tasks 1–3, data transformation, retries, and logging. A paid integration is not required; a mock is acceptable.\n\n## 3. Step-by-step work\n1. Combine earlier automation work in your own repository/workflow.\n2. Describe the trigger, input, main steps, error path, and output.\n3. Add input validation, retry limits, and duplicate-event protection.\n4. Test the workflow with at least five synthetic events.\n5. Measure duration, success rate, and manual steps reduced; label estimates separately.\n6. Document setup, limitations, and next steps.\n\n## 4. Concrete example and explanation\nApplication event → validate → store one record → notify. Include an invalid and a duplicate event among five inputs. This integrates the workflow; final handoff is Task 10.\n\n## 5. What to submit\nYour own GitHub repository/workflow export, diagram, test results, metrics, and case-study report. Clearly label results as measured or estimated.\n\n## 6. How to check your work\nShow normal, invalid, duplicate, and transient-failure outcomes. Define success rate as successful runs / all unique runs × 100 and state which runs count.","new_description":"[[AZ]]\nAvtomatlaşdırma üçün biznes axınını başdan sona qur, risk və human-in-the-loop nöqtələrini göstər.\n\nPulsuz alətlər: Python (free), diagrams.net, GitHub Free. Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nBuild an end-to-end business workflow and identify risk and human-approval points.\n\nFree tools: Python (free), diagrams.net, GitHub Free. See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** Lokal sintetik form → validator → admin approval mock → bildiriş yazısı prosesini tamamla.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **diagrams.net** — https://app.diagrams.net. Blank diagram seç, addımları oxlarla birləşdir və PNG/PDF çıxart.\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / automation-engineering / task-4` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. Əvvəlki workflow-ları bir sxemdə birləşdir və yalnız fiktiv məlumatla sına. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. Səhv giriş, təkrar event və admin təsdiqi gözləmə vəziyyətini əlavə et. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. 5 sınaq nəticəsini və prosesin əl ilə idarə edilən hissəsini sənədləşdir. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: Lokal sintetik form → validator → admin approval mock → bildiriş yazısı prosesini tamamla. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\nLokal sintetik form → validator → admin approval mock → bildiriş yazısı prosesini tamamla.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nBir biznes prosesini başlanğıcdan sona qədər avtomatlaşdırıb nəticəni ölçülə bilən case study kimi təqdim edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz Tapşırıq 1–3 workflow-ların, data transformation, retry və log əsasları. Ödənişli inteqrasiya tələb olunmur; mock alternativ qəbul edilir.\n\n## 3. Addım-addım icra\n1. Əvvəlki automation işlərini öz repo/workflow faylında birləşdir.\n2. Trigger, input, əsas addımlar, error path və output-u təsvir et.\n3. Input validation, retry limit və duplicate event qoruması əlavə et.\n4. Ən azı 5 sintetik event ilə workflow-u test et.\n5. Müddət, uğur faizi və manual addımların azalması kimi ölçüləri hesabla; təxminləri ayrıca qeyd et.\n6. Quraşdırma, məhdudiyyətlər və növbəti addımları yaz.\n\n## 4. Konkret nümunə və izah\nMüraciət event-i → sahələri yoxla → bir qeydi saxla → bildiriş yarat. Beş event-dən biri səhv, biri təkrar olsun. Bu inteqrasiya mərhələsidir; yekun texniki təhvil 10-cu tapşırıqda hazırlanır.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin/workflow export-u, diaqram, test nəticələri, ölçülər və case-study hesabatı. Uğur rəqəmləri real ölçü və ya təxmin kimi açıq işarələnməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nNormal, səhv, təkrar və müvəqqəti xəta yollarının nəticəsi göstərilib. Uğur faizi = uğurlu icra / bütün unikal icralar × 100; hansı icraların sayıldığı yazılıb.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** Integrate a fictional form, validator, mock human approval and notification log.\n\n## Free tools and platforms\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **diagrams.net** — https://app.diagrams.net. Create a blank diagram, connect steps with arrows and export PNG/PDF.\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / automation-engineering / task-4` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Connect earlier workflows in one diagram using fictional data. Show evidence in a file, local demo or measurable test.\n4. Handle invalid payloads, duplicates and waiting for human approval. Show evidence in a file, local demo or measurable test.\n5. Document five test results and the human-controlled steps. Show evidence in a file, local demo or measurable test.\n6. Verify this example: Integrate a fictional form, validator, mock human approval and notification log. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nIntegrate a fictional form, validator, mock human approval and notification log.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nAutomate a business process end to end and present the result as a measurable case study.\n\n## 2. Before you start\nYour workflows from Tasks 1–3, data transformation, retries, and logging. A paid integration is not required; a mock is acceptable.\n\n## 3. Step-by-step work\n1. Combine earlier automation work in your own repository/workflow.\n2. Describe the trigger, input, main steps, error path, and output.\n3. Add input validation, retry limits, and duplicate-event protection.\n4. Test the workflow with at least five synthetic events.\n5. Measure duration, success rate, and manual steps reduced; label estimates separately.\n6. Document setup, limitations, and next steps.\n\n## 4. Concrete example and explanation\nApplication event → validate → store one record → notify. Include an invalid and a duplicate event among five inputs. This integrates the workflow; final handoff is Task 10.\n\n## 5. What to submit\nYour own GitHub repository/workflow export, diagram, test results, metrics, and case-study report. Clearly label results as measured or estimated.\n\n## 6. How to check your work\nShow normal, invalid, duplicate, and transient-failure outcomes. Define success rate as successful runs / all unique runs × 100 and state which runs count."},{"slug":"automation-engineering","task_number":5,"title":"Data Transformation","old_description":"[[AZ]]\nMüxtəlif form girişlərini daxili vahid JSON modelinə çevir və keyfiyyət səhvlərini üzə çıxar.\n\n[[EN]]\nTransform varied form inputs into a consistent JSON model and surface data-quality issues.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nWorkflow-a daxil olan qarışıq JSON məlumatını sabit formata çevirəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz automation layihən, JSON, mapping və input validation əsasları.\n\n## 3. Addım-addım icra\n1. Öz workflow repo-nu davam etdir.\n2. Müxtəlif formatda ən azı 10 sintetik input nümunəsi yarat.\n3. Hədəf JSON schema və tələb olunan sahələri müəyyən et.\n4. Mapping, default dəyərlər və invalid input davranışını yaz.\n5. Orijinal input-u dəyişmədən saxla və transform edilmiş nəticəni ayrıca göstər.\n6. Valid/invalid nümunələr üçün test yaz.\n\n## 4. Konkret nümunə və izah\nMəsələn, `full_name` və `name` girişlərini çıxışda yalnız `name` sahəsinə uyğunlaşdır. Boş məcburi ad üçün səssizcə “Unknown” yazmaq əvəzinə validation xətası qaytar. İstifadə etdiyin standart dəyərləri ayrıca izah et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, mapping qaydaları, 10+ input nümunəsi, transform edilmiş nəticələr və testlər. Məlumat itkisi və default qərarları sənədləşdirilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n10 girişin gözlənilən çıxışı yazılıb. Boş, NULL və yanlış tip halları ayrıdır; orijinal məlumat saxlanır və heç bir sahə izahsız itmir.\n\n[[EN]]\n## 1. Goal\nTransform inconsistent incoming JSON into a consistent format.\n\n## 2. Before you start\nYour automation project, JSON, mapping, and input-validation basics.\n\n## 3. Step-by-step work\n1. Continue your own workflow repository.\n2. Create at least ten synthetic inputs with different formats.\n3. Define the target JSON schema and required fields.\n4. Specify mapping, default values, and invalid-input behavior.\n5. Keep original input unchanged and show transformed output separately.\n6. Write tests for valid and invalid examples.\n\n## 4. Concrete example and explanation\nMap input fields such as `full_name` and `name` into one output `name`. Reject a missing required name instead of silently inserting “Unknown”. Explain any defaults you deliberately use.\n\n## 5. What to submit\nYour own GitHub repository link, mapping rules, ten or more inputs, transformed outputs, and tests. Document data-loss risks and default-value decisions.\n\n## 6. How to check your work\nSpecify expected output for ten inputs. Distinguish missing, NULL, and wrong-type fields; retain the originals and explain any dropped fields.","new_description":"[[AZ]]\nMüxtəlif form girişlərini daxili vahid JSON modelinə çevir və keyfiyyət səhvlərini üzə çıxar.\n\nPulsuz alətlər: Python (free), Google Sheets (personal). Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nTransform varied form inputs into a consistent JSON model and surface data-quality issues.\n\nFree tools: Python (free), Google Sheets (personal). See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** `fullName`, `emailAddress` girişlərini `name`, `email` kimi vahid JSON formatına çevir.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **Google Sheets (personal)** — https://sheets.google.com. Sütun başlıqları, sintetik sətirlər və yoxlanıla bilən hesablamalar yarat.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / automation-engineering / task-5` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. Giriş və çıxış schema-larını iki nümunə JSON ilə göstər. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. Boş və səhv tipli sahələr üçün validation/fallback qaydası yaz. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. 5 qarışıq payload-u transformasiya edib before/after cədvəlinə əlavə et. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: `fullName`, `emailAddress` girişlərini `name`, `email` kimi vahid JSON formatına çevir. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\n`fullName`, `emailAddress` girişlərini `name`, `email` kimi vahid JSON formatına çevir.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nWorkflow-a daxil olan qarışıq JSON məlumatını sabit formata çevirəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz automation layihən, JSON, mapping və input validation əsasları.\n\n## 3. Addım-addım icra\n1. Öz workflow repo-nu davam etdir.\n2. Müxtəlif formatda ən azı 10 sintetik input nümunəsi yarat.\n3. Hədəf JSON schema və tələb olunan sahələri müəyyən et.\n4. Mapping, default dəyərlər və invalid input davranışını yaz.\n5. Orijinal input-u dəyişmədən saxla və transform edilmiş nəticəni ayrıca göstər.\n6. Valid/invalid nümunələr üçün test yaz.\n\n## 4. Konkret nümunə və izah\nMəsələn, `full_name` və `name` girişlərini çıxışda yalnız `name` sahəsinə uyğunlaşdır. Boş məcburi ad üçün səssizcə “Unknown” yazmaq əvəzinə validation xətası qaytar. İstifadə etdiyin standart dəyərləri ayrıca izah et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, mapping qaydaları, 10+ input nümunəsi, transform edilmiş nəticələr və testlər. Məlumat itkisi və default qərarları sənədləşdirilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n10 girişin gözlənilən çıxışı yazılıb. Boş, NULL və yanlış tip halları ayrıdır; orijinal məlumat saxlanır və heç bir sahə izahsız itmir.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** Normalize fictional fullName/emailAddress fields into a standard name/email JSON schema.\n\n## Free tools and platforms\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **Google Sheets (personal)** — https://sheets.google.com. Create labeled columns, fictional sample records and verifiable calculations.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / automation-engineering / task-5` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Define input/output schemas with two example JSON objects. Show evidence in a file, local demo or measurable test.\n4. Validate missing and wrong-type values with explicit fallback rules. Show evidence in a file, local demo or measurable test.\n5. Transform five varied samples and record before/after results. Show evidence in a file, local demo or measurable test.\n6. Verify this example: Normalize fictional fullName/emailAddress fields into a standard name/email JSON schema. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nNormalize fictional fullName/emailAddress fields into a standard name/email JSON schema.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nTransform inconsistent incoming JSON into a consistent format.\n\n## 2. Before you start\nYour automation project, JSON, mapping, and input-validation basics.\n\n## 3. Step-by-step work\n1. Continue your own workflow repository.\n2. Create at least ten synthetic inputs with different formats.\n3. Define the target JSON schema and required fields.\n4. Specify mapping, default values, and invalid-input behavior.\n5. Keep original input unchanged and show transformed output separately.\n6. Write tests for valid and invalid examples.\n\n## 4. Concrete example and explanation\nMap input fields such as `full_name` and `name` into one output `name`. Reject a missing required name instead of silently inserting “Unknown”. Explain any defaults you deliberately use.\n\n## 5. What to submit\nYour own GitHub repository link, mapping rules, ten or more inputs, transformed outputs, and tests. Document data-loss risks and default-value decisions.\n\n## 6. How to check your work\nSpecify expected output for ten inputs. Distinguish missing, NULL, and wrong-type fields; retain the originals and explain any dropped fields."},{"slug":"automation-engineering","task_number":6,"title":"API Integration","old_description":"[[AZ]]\nXarici API ilə limit, timeout və auth davranışı nəzərə alınmış inteqrasiya workflow-u qur.\n\n[[EN]]\nIntegrate an external API while accounting for rate limits, timeouts, and authentication.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nWorkflow-u API ilə əlaqələndirib nəticəni növbəti addıma ötürəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz automation repo-n, HTTP request, JSON, API status code və secret idarəetməsi.\n\n## 3. Addım-addım icra\n1. Öz layihəni davam etdir.\n2. Real xidmətə ehtiyac olmadan mock API endpoint hazırla.\n3. Request body və gözlənilən response schema-nı müəyyən et.\n4. Timeout, 4xx, 5xx və uğurlu cavab davranışını qur.\n5. API key istifadə edilirsə, onu environment secret kimi saxla; repo-ya yazma.\n6. Mock cavablarla success/error testləri işə sal.\n\n## 4. Konkret nümunə və izah\nMock API həqiqi xidmətə qoşulmadan əvvəlcədən hazırladığın cavabı qaytaran sınaqdır. Eyni lokal endpoint üçün 200, 400, 503 və gecikmiş cavab ssenarisi qur; iş axınının hər birində nə etdiyini göstər.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin/workflow export-u, API contract, mock endpoint və test nəticələri. Token və API key loglarda və repo-da olmamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nDörd ssenari təkrarlana bilir. Etibarsız cavab növbəti addıma düzgün məlumat kimi ötürülmür; xidmət ünvanı və gizli açarlar koddan ayrılıb.\n\n[[EN]]\n## 1. Goal\nConnect your workflow to an API and pass its response to the next step.\n\n## 2. Before you start\nYour automation repository, HTTP requests, JSON, API status codes, and secret management.\n\n## 3. Step-by-step work\n1. Continue your own project.\n2. Prepare a mock API endpoint that does not require a real external service.\n3. Define the request body and expected response schema.\n4. Handle timeout, 4xx, 5xx, and successful responses.\n5. If an API key is needed, store it as an environment secret; never commit it.\n6. Run success/error tests with mock responses.\n\n## 4. Concrete example and explanation\nA mock API returns prepared test responses without contacting a real service. Simulate 200, 400, 503, and a delayed response from a local endpoint, and show the workflow outcome for each.\n\n## 5. What to submit\nYour own GitHub repository/workflow export, API contract, mock endpoint, and test results. Tokens and API keys must not appear in logs or the repository.\n\n## 6. How to check your work\nAll four scenarios are reproducible. Invalid responses cannot pass as valid data; configure service addresses and secrets outside source code.","new_description":"[[AZ]]\nXarici API ilə limit, timeout və auth davranışı nəzərə alınmış inteqrasiya workflow-u qur.\n\nPulsuz alətlər: Python (free), FastAPI (open source), curl. Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nIntegrate an external API while accounting for rate limits, timeouts, and authentication.\n\nFree tools: Python (free), FastAPI (open source), curl. See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** Lokal `GET /demo-records` endpoint-inə timeout və 429/500 mock cavablarını sına.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Python layihəsində lokal HTTP endpoint və Pydantic input modeli yarat; ödənişli server lazım deyil.\n- **curl** — https://curl.se. Yalnız öz lokal HTTP servisindən test sorğuları göndər, status və JSON cavablarını yoxla.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / automation-engineering / task-6` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. Servis mock-u ilə lokal HTTP inteqrasiyası qur; real API açarı istifadə etmə. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. Timeout və limit xətaları üçün təhlükəsiz fallback və retry limitini yaz. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. JSON sahələrini doğrula və ən azı 4 status halını test et. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: Lokal `GET /demo-records` endpoint-inə timeout və 429/500 mock cavablarını sına. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\nLokal `GET /demo-records` endpoint-inə timeout və 429/500 mock cavablarını sına.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nWorkflow-u API ilə əlaqələndirib nəticəni növbəti addıma ötürəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz automation repo-n, HTTP request, JSON, API status code və secret idarəetməsi.\n\n## 3. Addım-addım icra\n1. Öz layihəni davam etdir.\n2. Real xidmətə ehtiyac olmadan mock API endpoint hazırla.\n3. Request body və gözlənilən response schema-nı müəyyən et.\n4. Timeout, 4xx, 5xx və uğurlu cavab davranışını qur.\n5. API key istifadə edilirsə, onu environment secret kimi saxla; repo-ya yazma.\n6. Mock cavablarla success/error testləri işə sal.\n\n## 4. Konkret nümunə və izah\nMock API həqiqi xidmətə qoşulmadan əvvəlcədən hazırladığın cavabı qaytaran sınaqdır. Eyni lokal endpoint üçün 200, 400, 503 və gecikmiş cavab ssenarisi qur; iş axınının hər birində nə etdiyini göstər.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin/workflow export-u, API contract, mock endpoint və test nəticələri. Token və API key loglarda və repo-da olmamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nDörd ssenari təkrarlana bilir. Etibarsız cavab növbəti addıma düzgün məlumat kimi ötürülmür; xidmət ünvanı və gizli açarlar koddan ayrılıb.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** Test a local GET /demo-records integration with mock 429/500 and timeout responses.\n\n## Free tools and platforms\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Create local Python HTTP endpoints with Pydantic validation; paid hosting is unnecessary.\n- **curl** — https://curl.se. Send test requests only to authorized local endpoints and check status/JSON results.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / automation-engineering / task-6` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Create a localhost HTTP mock without real API credentials. Show evidence in a file, local demo or measurable test.\n4. Add safe timeout, rate-limit and failure handling with bounded retries. Show evidence in a file, local demo or measurable test.\n5. Validate JSON and test at least four response scenarios. Show evidence in a file, local demo or measurable test.\n6. Verify this example: Test a local GET /demo-records integration with mock 429/500 and timeout responses. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nTest a local GET /demo-records integration with mock 429/500 and timeout responses.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nConnect your workflow to an API and pass its response to the next step.\n\n## 2. Before you start\nYour automation repository, HTTP requests, JSON, API status codes, and secret management.\n\n## 3. Step-by-step work\n1. Continue your own project.\n2. Prepare a mock API endpoint that does not require a real external service.\n3. Define the request body and expected response schema.\n4. Handle timeout, 4xx, 5xx, and successful responses.\n5. If an API key is needed, store it as an environment secret; never commit it.\n6. Run success/error tests with mock responses.\n\n## 4. Concrete example and explanation\nA mock API returns prepared test responses without contacting a real service. Simulate 200, 400, 503, and a delayed response from a local endpoint, and show the workflow outcome for each.\n\n## 5. What to submit\nYour own GitHub repository/workflow export, API contract, mock endpoint, and test results. Tokens and API keys must not appear in logs or the repository.\n\n## 6. How to check your work\nAll four scenarios are reproducible. Invalid responses cannot pass as valid data; configure service addresses and secrets outside source code."},{"slug":"automation-engineering","task_number":7,"title":"Scheduled Workflow","old_description":"[[AZ]]\nVaxt zonası, duplicate run və missed execution halları olan etibarlı schedule workflow qur.\n\n[[EN]]\nBuild a reliable scheduled workflow that handles time zones, duplicate runs, and missed executions.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nWorkflow-u müəyyən vaxtda və ya intervalda avtomatik başladacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz automation layihən, cron/schedule anlayışı və idempotency əsasları. Ödənişli scheduler yoxdursa, lokal planı və simulyasiyanı sənədləşdir.\n\n## 3. Addım-addım icra\n1. Öz workflow repo-nu davam etdir.\n2. İşə düşmə intervalını və timezone-u dəqiq yaz.\n3. Schedule trigger əlavə et və işləmə tarixini logla.\n4. Eyni interval iki dəfə işə düşərsə dublikat nəticənin qarşısını al.\n5. Uğurlu run, missed run və retry ssenarilərini yoxla.\n6. Manual run və dayandırma qaydasını README-də sənədləşdir.\n\n## 4. Konkret nümunə və izah\nPlanı “hər gün Bakı vaxtı ilə saat 09:00” kimi yaz. İcra açarı həmin tarix olsun: eyni tarix təkrar başladıqda ikinci nəticə yaratma. Scheduler yoxdursa, iki ardıcıl tarixi əl ilə ötürərək davranışı simulyasiya et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin/workflow export-u, schedule konfiqurasiyası, timezone qeydi, run log-ları və testlər. Dublikat icra idarə olunmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nSaat qurşağı, normal və buraxılmış icranın bərpası sənədləşib. Eyni icra açarı ilə təkrar sınaq əlavə nəticə yaratmır; dayandırma qaydası işləyir.\n\n[[EN]]\n## 1. Goal\nRun a workflow automatically at a specified time or interval.\n\n## 2. Before you start\nYour automation project, scheduling/cron concepts, and idempotency. If no paid scheduler is available, document a local plan and simulation.\n\n## 3. Step-by-step work\n1. Continue your own workflow repository.\n2. Specify the interval and timezone clearly.\n3. Add a scheduled trigger and log each run time.\n4. Prevent duplicate results if a schedule fires twice.\n5. Check successful runs, missed runs, and retry scenarios.\n6. Document manual execution and how to disable the schedule in the README.\n\n## 4. Concrete example and explanation\nDefine a schedule such as “daily at 09:00 Asia/Baku”. Use the scheduled date as a run key so a duplicate start cannot create a second result. Without a scheduler, simulate two dates manually.\n\n## 5. What to submit\nYour own GitHub repository/workflow export, schedule configuration, timezone note, run logs, and tests. Duplicate execution must be handled.\n\n## 6. How to check your work\nDocument timezone, normal execution, and missed-run recovery. Repeating a run key creates no extra output; the stop procedure works.","new_description":"[[AZ]]\nVaxt zonası, duplicate run və missed execution halları olan etibarlı schedule workflow qur.\n\nPulsuz alətlər: Python (free), Google Docs (personal). Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nBuild a reliable scheduled workflow that handles time zones, duplicate runs, and missed executions.\n\nFree tools: Python (free), Google Docs (personal). See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** Windows Task Scheduler və ya lokal Python timer ilə gündəlik yoxlamanın necə işə düşəcəyini simulyasiya et.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / automation-engineering / task-7` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. Saat zonasını Asia/Baku kimi sənədləşdir, 2 run nümunəsi qur. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. Eyni vaxtda iki iş düşdükdə duplicate-in qarşısını alan açar istifadə et. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. Missed run və yenidən başlatma davranışını synthetic log-da göstər. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: Windows Task Scheduler və ya lokal Python timer ilə gündəlik yoxlamanın necə işə düşəcəyini simulyasiya et. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\nWindows Task Scheduler və ya lokal Python timer ilə gündəlik yoxlamanın necə işə düşəcəyini simulyasiya et.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nWorkflow-u müəyyən vaxtda və ya intervalda avtomatik başladacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz automation layihən, cron/schedule anlayışı və idempotency əsasları. Ödənişli scheduler yoxdursa, lokal planı və simulyasiyanı sənədləşdir.\n\n## 3. Addım-addım icra\n1. Öz workflow repo-nu davam etdir.\n2. İşə düşmə intervalını və timezone-u dəqiq yaz.\n3. Schedule trigger əlavə et və işləmə tarixini logla.\n4. Eyni interval iki dəfə işə düşərsə dublikat nəticənin qarşısını al.\n5. Uğurlu run, missed run və retry ssenarilərini yoxla.\n6. Manual run və dayandırma qaydasını README-də sənədləşdir.\n\n## 4. Konkret nümunə və izah\nPlanı “hər gün Bakı vaxtı ilə saat 09:00” kimi yaz. İcra açarı həmin tarix olsun: eyni tarix təkrar başladıqda ikinci nəticə yaratma. Scheduler yoxdursa, iki ardıcıl tarixi əl ilə ötürərək davranışı simulyasiya et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin/workflow export-u, schedule konfiqurasiyası, timezone qeydi, run log-ları və testlər. Dublikat icra idarə olunmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nSaat qurşağı, normal və buraxılmış icranın bərpası sənədləşib. Eyni icra açarı ilə təkrar sınaq əlavə nəticə yaratmır; dayandırma qaydası işləyir.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** Simulate a daily job using Windows Task Scheduler or a local Python timer.\n\n## Free tools and platforms\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / automation-engineering / task-7` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Document timezone and two scheduled-run examples. Show evidence in a file, local demo or measurable test.\n4. Use a unique run key to prevent overlapping duplicates. Show evidence in a file, local demo or measurable test.\n5. Simulate a missed run and restart scenario using local logs. Show evidence in a file, local demo or measurable test.\n6. Verify this example: Simulate a daily job using Windows Task Scheduler or a local Python timer. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nSimulate a daily job using Windows Task Scheduler or a local Python timer.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nRun a workflow automatically at a specified time or interval.\n\n## 2. Before you start\nYour automation project, scheduling/cron concepts, and idempotency. If no paid scheduler is available, document a local plan and simulation.\n\n## 3. Step-by-step work\n1. Continue your own workflow repository.\n2. Specify the interval and timezone clearly.\n3. Add a scheduled trigger and log each run time.\n4. Prevent duplicate results if a schedule fires twice.\n5. Check successful runs, missed runs, and retry scenarios.\n6. Document manual execution and how to disable the schedule in the README.\n\n## 4. Concrete example and explanation\nDefine a schedule such as “daily at 09:00 Asia/Baku”. Use the scheduled date as a run key so a duplicate start cannot create a second result. Without a scheduler, simulate two dates manually.\n\n## 5. What to submit\nYour own GitHub repository/workflow export, schedule configuration, timezone note, run logs, and tests. Duplicate execution must be handled.\n\n## 6. How to check your work\nDocument timezone, normal execution, and missed-run recovery. Repeating a run key creates no extra output; the stop procedure works."},{"slug":"automation-engineering","task_number":8,"title":"Notification Flow","old_description":"[[AZ]]\nBildiriş seçimlərini, template-ləri və uğursuz göndərişləri idarə edən notification flow qur.\n\n[[EN]]\nBuild a notification flow with preference checks, templates, and delivery-failure handling.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nWorkflow tamamlananda və ya xəta verəndə uyğun bildiriş göndərəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz automation layihən, workflow statusları və bildiriş kanalı. Real email/chat hesabı yoxdursa, mock notification istifadə et.\n\n## 3. Addım-addım icra\n1. Öz layihəni davam etdir.\n2. Success və failure üçün bildiriş qaydaları yaz.\n3. Mesajda run ID, status və təhlükəsiz xəta xülasəsi göstər.\n4. Şəxsi məlumat, token və tam payload göndərmə.\n5. Eyni event üçün təkrar bildirişləri məhdudlaşdır.\n6. Uğurlu, uğursuz və notification provider xətası üçün test yaz.\n\n## 4. Konkret nümunə və izah\nUğurlu mesaj: “run-12 tamamlandı”. Xəta mesajı: “run-12: xidmət vaxtında cavab vermədi; 3 cəhd”. Əvvəlcə mesajları lokal fayla yazan simulyasiya kanalı istifadə edə bilərsən.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin/workflow export-u, mesaj şablonları, mock bildirişlər və testlər. Bildirişlər həssas məlumat sızdırmamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nUğur və xəta fərqli şablondadır. Təkrar event təkrar bildiriş yaratmır; bildiriş xidməti işləməyəndə əsas icranın nəticəsi itmir.\n\n[[EN]]\n## 1. Goal\nSend a suitable notification when a workflow succeeds or fails.\n\n## 2. Before you start\nYour automation project, workflow states, and notification channel. Use mock notifications if no real email/chat account is available.\n\n## 3. Step-by-step work\n1. Continue your own project.\n2. Define notification rules for success and failure.\n3. Include run ID, status, and a safe error summary.\n4. Do not send personal data, tokens, or full payloads.\n5. Limit duplicate notifications for the same event.\n6. Test success, failure, and notification-provider errors.\n\n## 4. Concrete example and explanation\nSuccess: “run-12 completed”. Failure: “run-12: service timed out after 3 attempts”. A local file can act as the simulated notification channel.\n\n## 5. What to submit\nYour own GitHub repository/workflow export, message templates, mock notifications, and tests. Notifications must not leak sensitive data.\n\n## 6. How to check your work\nUse distinct success and failure templates. Duplicate events cannot duplicate notifications; notification failure must not erase the main run result.","new_description":"[[AZ]]\nBildiriş seçimlərini, template-ləri və uğursuz göndərişləri idarə edən notification flow qur.\n\nPulsuz alətlər: Python (free), Google Docs (personal). Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nBuild a notification flow with preference checks, templates, and delivery-failure handling.\n\nFree tools: Python (free), Google Docs (personal). See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** Yalnız `notifications.log` faylına 'approved'/'failed' statuslu uydurma bildirişlər yaz.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / automation-engineering / task-8` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. Bildiriş üçün subject/body şablonlarını müəyyən et. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. İstifadəçi seçimlərini və olmayan alıcını yoxlayan filtr qur. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. Uğurlu, bloklanan və retry halları üçün log sübutu təqdim et. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: Yalnız `notifications.log` faylına 'approved'/'failed' statuslu uydurma bildirişlər yaz. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\nYalnız `notifications.log` faylına 'approved'/'failed' statuslu uydurma bildirişlər yaz.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nWorkflow tamamlananda və ya xəta verəndə uyğun bildiriş göndərəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz automation layihən, workflow statusları və bildiriş kanalı. Real email/chat hesabı yoxdursa, mock notification istifadə et.\n\n## 3. Addım-addım icra\n1. Öz layihəni davam etdir.\n2. Success və failure üçün bildiriş qaydaları yaz.\n3. Mesajda run ID, status və təhlükəsiz xəta xülasəsi göstər.\n4. Şəxsi məlumat, token və tam payload göndərmə.\n5. Eyni event üçün təkrar bildirişləri məhdudlaşdır.\n6. Uğurlu, uğursuz və notification provider xətası üçün test yaz.\n\n## 4. Konkret nümunə və izah\nUğurlu mesaj: “run-12 tamamlandı”. Xəta mesajı: “run-12: xidmət vaxtında cavab vermədi; 3 cəhd”. Əvvəlcə mesajları lokal fayla yazan simulyasiya kanalı istifadə edə bilərsən.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin/workflow export-u, mesaj şablonları, mock bildirişlər və testlər. Bildirişlər həssas məlumat sızdırmamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nUğur və xəta fərqli şablondadır. Təkrar event təkrar bildiriş yaratmır; bildiriş xidməti işləməyəndə əsas icranın nəticəsi itmir.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** Write fictional approved/failed notifications to a local log, not real recipients.\n\n## Free tools and platforms\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / automation-engineering / task-8` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Define subject/body templates for fictional notifications. Show evidence in a file, local demo or measurable test.\n4. Apply preference and recipient checks before creating a notification. Show evidence in a file, local demo or measurable test.\n5. Demonstrate success, suppression and retry in a local log. Show evidence in a file, local demo or measurable test.\n6. Verify this example: Write fictional approved/failed notifications to a local log, not real recipients. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nWrite fictional approved/failed notifications to a local log, not real recipients.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nSend a suitable notification when a workflow succeeds or fails.\n\n## 2. Before you start\nYour automation project, workflow states, and notification channel. Use mock notifications if no real email/chat account is available.\n\n## 3. Step-by-step work\n1. Continue your own project.\n2. Define notification rules for success and failure.\n3. Include run ID, status, and a safe error summary.\n4. Do not send personal data, tokens, or full payloads.\n5. Limit duplicate notifications for the same event.\n6. Test success, failure, and notification-provider errors.\n\n## 4. Concrete example and explanation\nSuccess: “run-12 completed”. Failure: “run-12: service timed out after 3 attempts”. A local file can act as the simulated notification channel.\n\n## 5. What to submit\nYour own GitHub repository/workflow export, message templates, mock notifications, and tests. Notifications must not leak sensitive data.\n\n## 6. How to check your work\nUse distinct success and failure templates. Duplicate events cannot duplicate notifications; notification failure must not erase the main run result."},{"slug":"automation-engineering","task_number":9,"title":"Automation Metrics","old_description":"[[AZ]]\nWorkflow-lar üçün əməliyyat KPI-ları müəyyən et və alert hədlərini əsaslandır.\n\n[[EN]]\nDefine operational KPIs for workflows and justify alert thresholds.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nAvtomatlaşdırmanın effektivliyini ölçən göstəricilər hazırlayıb nəticəni əvvəlcədən müəyyən edilmiş meyarlarla qiymətləndirəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz workflow run log-ları, duration, success/failure və manual effort anlayışları. Real ölçü yoxdursa, simulyasiyanı ayrıca işarələ.\n\n## 3. Addım-addım icra\n1. Öz automation repo-nu davam etdir.\n2. 10+ sintetik run nəticəsi hazırla və ya mövcud run-ları export et.\n3. Uğur faizi, orta müddət, retry sayı və manual addımların sayını hesabla.\n4. Əvvəlcədən uğur meyarı təyin et və nəticə ilə müqayisə et.\n5. Zəif nəticənin səbəbini və növbəti yaxşılaşdırmanı izah et.\n6. Ölçmə formulalarını README-də sənədləşdir.\n\n## 4. Konkret nümunə və izah\n10 unikal icradan 8-i uğurludursa uğur faizi 80%-dir. Orta müddət bütün seçilmiş icraların müddətlərinin cəmi / sayıdır. Əl əməyinə qənaəti hesablamaq üçün müqayisə edilən eyni addımları əvvəlcədən yaz.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, metrics cədvəli/diaqramı, formulalar və nəticə hesabatı. Simulyasiya olunan rəqəmlər real production göstəricisi kimi təqdim edilməməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nHər göstəricinin formulu, vahidi və daxil edilən icraları var. Cədvəlin rəqəmləri loglarla uyğun gəlir; uğur həddi nəticələrə baxmazdan əvvəl seçilib.\n\n[[EN]]\n## 1. Goal\nMeasure automation effectiveness and evaluate it against predefined criteria.\n\n## 2. Before you start\nYour workflow run logs, duration, success/failure, and manual-effort concepts. Clearly label simulated data.\n\n## 3. Step-by-step work\n1. Continue your own automation repository.\n2. Prepare ten or more synthetic run results or export existing runs.\n3. Calculate success rate, average duration, retry count, and manual steps.\n4. Define success criteria in advance and compare the results.\n5. Explain poor results and the next improvement.\n6. Document metric formulas in the README.\n\n## 4. Concrete example and explanation\nEight successes among ten unique runs means 80%. Mean duration is the sum of selected run durations divided by their count. Define comparable manual steps before estimating time saved.\n\n## 5. What to submit\nYour own GitHub repository link, metrics table/chart, formulas, and report. Simulated values must not be presented as real production metrics.\n\n## 6. How to check your work\nSpecify each formula, unit, and included runs. Values match logs, and the success threshold is chosen before viewing results.","new_description":"[[AZ]]\nWorkflow-lar üçün əməliyyat KPI-ları müəyyən et və alert hədlərini əsaslandır.\n\nPulsuz alətlər: Google Sheets (personal), Python (free). Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nDefine operational KPIs for workflows and justify alert thresholds.\n\nFree tools: Google Sheets (personal), Python (free). See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** 20 simulyasiya workflow run üçün success_rate, median_duration və retry_count hesabla.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **Google Sheets (personal)** — https://sheets.google.com. Sütun başlıqları, sintetik sətirlər və yoxlanıla bilən hesablamalar yarat.\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / automation-engineering / task-9` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. Run ID, status, duration, retries sütunları qur. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. Ölçüləri formulası ilə hesabla və uğursuz run-ları ayrıca say. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. Fərz etdiyin alert hədlərini və false alarm riskini izah et. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: 20 simulyasiya workflow run üçün success_rate, median_duration və retry_count hesabla. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\n20 simulyasiya workflow run üçün success_rate, median_duration və retry_count hesabla.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nAvtomatlaşdırmanın effektivliyini ölçən göstəricilər hazırlayıb nəticəni əvvəlcədən müəyyən edilmiş meyarlarla qiymətləndirəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz workflow run log-ları, duration, success/failure və manual effort anlayışları. Real ölçü yoxdursa, simulyasiyanı ayrıca işarələ.\n\n## 3. Addım-addım icra\n1. Öz automation repo-nu davam etdir.\n2. 10+ sintetik run nəticəsi hazırla və ya mövcud run-ları export et.\n3. Uğur faizi, orta müddət, retry sayı və manual addımların sayını hesabla.\n4. Əvvəlcədən uğur meyarı təyin et və nəticə ilə müqayisə et.\n5. Zəif nəticənin səbəbini və növbəti yaxşılaşdırmanı izah et.\n6. Ölçmə formulalarını README-də sənədləşdir.\n\n## 4. Konkret nümunə və izah\n10 unikal icradan 8-i uğurludursa uğur faizi 80%-dir. Orta müddət bütün seçilmiş icraların müddətlərinin cəmi / sayıdır. Əl əməyinə qənaəti hesablamaq üçün müqayisə edilən eyni addımları əvvəlcədən yaz.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, metrics cədvəli/diaqramı, formulalar və nəticə hesabatı. Simulyasiya olunan rəqəmlər real production göstəricisi kimi təqdim edilməməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nHər göstəricinin formulu, vahidi və daxil edilən icraları var. Cədvəlin rəqəmləri loglarla uyğun gəlir; uğur həddi nəticələrə baxmazdan əvvəl seçilib.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** Calculate success rate, median duration and retries from 20 simulated workflow runs.\n\n## Free tools and platforms\n- **Google Sheets (personal)** — https://sheets.google.com. Create labeled columns, fictional sample records and verifiable calculations.\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / automation-engineering / task-9` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Create columns for run ID, status, duration and retry count. Show evidence in a file, local demo or measurable test.\n4. Calculate summary KPIs and inspect failed runs. Show evidence in a file, local demo or measurable test.\n5. Explain alert thresholds and potential false positives. Show evidence in a file, local demo or measurable test.\n6. Verify this example: Calculate success rate, median duration and retries from 20 simulated workflow runs. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nCalculate success rate, median duration and retries from 20 simulated workflow runs.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nMeasure automation effectiveness and evaluate it against predefined criteria.\n\n## 2. Before you start\nYour workflow run logs, duration, success/failure, and manual-effort concepts. Clearly label simulated data.\n\n## 3. Step-by-step work\n1. Continue your own automation repository.\n2. Prepare ten or more synthetic run results or export existing runs.\n3. Calculate success rate, average duration, retry count, and manual steps.\n4. Define success criteria in advance and compare the results.\n5. Explain poor results and the next improvement.\n6. Document metric formulas in the README.\n\n## 4. Concrete example and explanation\nEight successes among ten unique runs means 80%. Mean duration is the sum of selected run durations divided by their count. Define comparable manual steps before estimating time saved.\n\n## 5. What to submit\nYour own GitHub repository link, metrics table/chart, formulas, and report. Simulated values must not be presented as real production metrics.\n\n## 6. How to check your work\nSpecify each formula, unit, and included runs. Values match logs, and the success threshold is chosen before viewing results."},{"slug":"automation-engineering","task_number":10,"title":"Automation Case Handoff","old_description":"[[AZ]]\nWorkflow-u komanda üçün təhvil ver: quraşdırma, credential, monitorinq və bərpa addımlarını yaz.\n\n[[EN]]\nHand off a workflow with setup, credential, monitoring, and recovery instructions.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nWorkflow-u başqa şəxsin qura, yoxlaya və davam etdirə bilməsi üçün texniki təhvil paketi hazırlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz Tapşırıq 1–9 workflow-ların, konfiqurasiya, error handling, monitoring və testlər.\n\n## 3. Addım-addım icra\n1. Əvvəlki automation layihəni öz repo/workflow faylında davam etdir.\n2. Setup, trigger, environment dəyişənləri və manual run qaydasını yaz.\n3. Workflow diaqramı, data mapping, retry və notification qaydalarını sənədləşdir.\n4. Test nəticələri, metriklər, məlum məhdudiyyətlər və failure recovery-ni əlavə et.\n5. Secret-ləri çıxar və təmiz mühitdə quraşdırma təlimatını yoxla.\n6. Növbəti 3 yaxşılaşdırmanı prioritetləşdir.\n\n## 4. Konkret nümunə və izah\nYeni qovluqda iş axınını quraşdır, nümunə event-i göndər və gözlənilən çıxışı müqayisə et. Xəta olarsa hansı loga baxılacağını və təhlükəsiz təkrar icranın necə başladılacağını yaz.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin/workflow export-u, README, diaqram, test/metrics hesabatı və növbəti addımlar. Başqa şəxs təlimatla workflow-u yenidən qura bilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nTəmiz quraşdırma və normal/xəta yolu təkrarlanır. Konfiqurasiya nümunəsində real açar yoxdur; ölçmə hesabatı və növbəti üç iş paketə daxildir.\n\n[[EN]]\n## 1. Goal\nPrepare a handoff package so another person can set up, verify, and maintain your workflow.\n\n## 2. Before you start\nYour workflow artifacts from Tasks 1–9, configuration, error handling, monitoring, and tests.\n\n## 3. Step-by-step work\n1. Continue your earlier automation project in your own repository/workflow file.\n2. Document setup, triggers, environment variables, and manual execution.\n3. Document the workflow diagram, data mapping, retries, and notifications.\n4. Include test results, metrics, limitations, and failure recovery.\n5. Remove secrets and verify the setup instructions in a clean environment.\n6. Prioritize the next three improvements.\n\n## 4. Concrete example and explanation\nSet up in a new folder, send the sample event, and compare the expected output. Explain which log to inspect after failure and how to retry safely.\n\n## 5. What to submit\nYour own GitHub repository/workflow export, README, diagram, test/metrics report, and next steps. Another person must be able to recreate the workflow from the instructions.\n\n## 6. How to check your work\nReproduce clean setup plus success/failure paths. Configuration examples contain no real keys; include measurements and three prioritized next steps.","new_description":"[[AZ]]\nWorkflow-u komanda üçün təhvil ver: quraşdırma, credential, monitorinq və bərpa addımlarını yaz.\n\nPulsuz alətlər: GitHub Free, Google Docs (personal), diagrams.net. Geniş izah tapşırıq daxilində verilib.\n\n[[EN]]\nHand off a workflow with setup, credential, monitoring, and recovery instructions.\n\nFree tools: GitHub Free, Google Docs (personal), diagrams.net. See the assignment for a detailed guide.","new_instructions":"[[AZ]]\n## Sadə dildə tapşırığın izahı\nBu iş başlanğıc səviyyəsi üçün **praktik məşqdir**: sadəcə nəzəri mətn yox, işləyən demo, yoxlanıla bilən fayl və ya diaqram hazırlayacaqsan.\n**Nümunə:** Yeni developer lokal webhook → validator → notification log axınını README ilə işlədə bilsin.\n\n## İstifadə edəcəyin pulsuz proqramlar və platformalar\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n- **diagrams.net** — https://app.diagrams.net. Blank diagram seç, addımları oxlarla birləşdir və PNG/PDF çıxart.\n> Pullu plan, ödəniş kartı, ödənişli API və real istifadəçi məlumatı lazım deyil. Pulsuz kvota bitdikdə lokal alternativ istifadə et.\n\n## Addım-addım icra — 8 mərhələ\n1. Lokal `Talora / automation-engineering / task-10` qovluğu yarat. Hazır kod/dizaynın varsa onun nüsxəsindən başla; yalnız özünə məxsus, icazəli və ya sintetik məlumatdan istifadə et.\n2. Tapşırığın məqsədini bir cümlədə yaz: bu nəticə kimin hansı problemini həll edir və uğurlu nəticəni necə tanıyacaqsan?\n3. Repo-ya quraşdırma addımları, config nümunəsi və flow diaqramı əlavə et. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n4. Risklər, retry, monitorinq və manual təsdiq yerini sənədləşdir. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n5. 2 uğurlu, 2 xəta ssenarisinin ekran/log nəticəsini təhvil ver. Nəticəni real fayl, lokal işləyən demo və ya ölçülən sınaqla göstər.\n6. Praktik yoxlama: Yeni developer lokal webhook → validator → notification log axınını README ilə işlədə bilsin. Uğurlu və səhv/boş giriş sınağını sənədləşdir; uyğun deyilsə niyə tətbiq olunmadığını izah et.\n7. Orijinal tapşırıqda istənən GitHub repo, PDF, layihə faylı və ya linki hazırla. README, test və screenshot əlavə et, sirləri çıxart.\n8. Aşağıdakı əvvəlki rəsmi tələblərin hamısını yoxla; 3–5 cümlədə nəticəni, istifadə etdiyin alətləri və məhdudiyyəti izah et.\n\n## İşlənmiş nümunənin nəticəsi\nYeni developer lokal webhook → validator → notification log axınını README ilə işlədə bilsin.\nBu nümunəni olduğu kimi köçürmə: öz sintetik testini və qərarının səbəbini göstər.\n\n## Nəyi təhvil verməlisən?\n- **Əsas nəticə:** əvvəlki rəsmi şərtlərdə tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə:** redaktə edilən kod/dizayn, uyğun test və README, istifadə olunan pulsuz alətlərin adları.\n- **Sübut:** sintetik input və gözlənilən output, screenshot və ya test log-u (tapşırığa uyğun).\n- **İzah:** 3–5 cümləlik nəticə, mənbələr və məhdudiyyətlər; şəxsi məlumat/şifrə paylaşma.\n\n## 100 ballıq özünü yoxlama meyarları\n- **40 bal:** əsas texniki addımlar və rəsmi təhvil nəticələri tamamdır.\n- **25 bal:** nümunə işləyir, düzgünlük və mənfi hallar test edilib.\n- **15 bal:** struktur, README, fayl adları və oxunaqlıq aydındır.\n- **10 bal:** təhlükəsizlik, mənbə hüququ və pulsuz alət qaydaları gözlənilib.\n- **10 bal:** öz izahın, məhdudiyyət və təkmilləşdirmə qeydləri var.\n**Qeyd:** Bu rubrik öyrənməyə kömək edən nümunədir; əvvəlki rəsmi meyarları və artıq qiymətləndirilmiş təqdimatları dəyişmir.\n\n## Göndərməzdən əvvəl\n- Orijinal tapşırığın tələb etdiyi təqdimat formatı saxlanılıb.\n- Link oxunur, kod/fayl açılır, şəxsi məlumatlar və gizli açarlar yoxdur.\n- Test yalnız özünə məxsus və ya icazə verilmiş laboratoriyada aparılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nWorkflow-u başqa şəxsin qura, yoxlaya və davam etdirə bilməsi üçün texniki təhvil paketi hazırlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz Tapşırıq 1–9 workflow-ların, konfiqurasiya, error handling, monitoring və testlər.\n\n## 3. Addım-addım icra\n1. Əvvəlki automation layihəni öz repo/workflow faylında davam etdir.\n2. Setup, trigger, environment dəyişənləri və manual run qaydasını yaz.\n3. Workflow diaqramı, data mapping, retry və notification qaydalarını sənədləşdir.\n4. Test nəticələri, metriklər, məlum məhdudiyyətlər və failure recovery-ni əlavə et.\n5. Secret-ləri çıxar və təmiz mühitdə quraşdırma təlimatını yoxla.\n6. Növbəti 3 yaxşılaşdırmanı prioritetləşdir.\n\n## 4. Konkret nümunə və izah\nYeni qovluqda iş axınını quraşdır, nümunə event-i göndər və gözlənilən çıxışı müqayisə et. Xəta olarsa hansı loga baxılacağını və təhlükəsiz təkrar icranın necə başladılacağını yaz.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin/workflow export-u, README, diaqram, test/metrics hesabatı və növbəti addımlar. Başqa şəxs təlimatla workflow-u yenidən qura bilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nTəmiz quraşdırma və normal/xəta yolu təkrarlanır. Konfiqurasiya nümunəsində real açar yoxdur; ölçmə hesabatı və növbəti üç iş paketə daxildir.\n\n[[EN]]\n## Beginner-friendly explanation\nThis is a **hands-on beginner assignment**. Produce a runnable example, verifiable file or clear diagram rather than theory alone.\n**Example:** Enable another developer to run the local webhook → validator → notification log workflow.\n\n## Free tools and platforms\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n- **diagrams.net** — https://app.diagrams.net. Create a blank diagram, connect steps with arrows and export PNG/PDF.\n> No paid subscriptions, credit cards, paid APIs or real personal data are required. If a free tier is exhausted, use a local option.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / automation-engineering / task-10` folder. Reuse earlier work where appropriate, but use only owned, licensed or fictional data.\n2. State who the assignment helps, what problem it solves and how you will verify success.\n3. Document setup, sample config and the workflow diagram. Show evidence in a file, local demo or measurable test.\n4. Describe risks, retries, monitoring and manual approval checkpoints. Show evidence in a file, local demo or measurable test.\n5. Include evidence for two successful and two failed runs. Show evidence in a file, local demo or measurable test.\n6. Verify this example: Enable another developer to run the local webhook → validator → notification log workflow. Record one successful and one invalid/empty case, or explain why it does not apply.\n7. Prepare the exact original GitHub repository, PDF, project file or link. Include a README and evidence without exposing credentials.\n8. Check every original requirement below and write a three-to-five sentence summary of the result, free tools and limitations.\n\n## Worked example and expected result\nEnable another developer to run the local webhook → validator → notification log workflow.\nAdapt the example to your own fictional case rather than copying it; explain how you checked the outcome.\n\n## What to submit\n- **Main deliverable:** the original required file, GitHub repository or link.\n- **Source:** editable code/design, tests and README as applicable, with names of free tools.\n- **Evidence:** fictional inputs/expected outputs, screenshots or test logs as appropriate.\n- **Explanation:** a three-to-five sentence result, citations and limitations; never include private data or credentials.\n\n## Self-check rubric (100 points)\n- **40:** essential technical work and official deliverables.\n- **25:** correct and tested example, including negative cases.\n- **15:** clear structure, README and filenames.\n- **10:** safety, licensing and no-cost tool choices.\n- **10:** your own reasoning and suggested improvements.\n**Note:** This is learning guidance; official requirements and earlier graded submissions remain unchanged.\n\n## Final checklist\n- Keep the original submission format and requirements.\n- Verify reviewer access to files and links; remove credentials and personal data.\n- Test only systems you own or have explicit permission to assess.\n\n## Original assignment requirements (unchanged)\n## 1. Goal\nPrepare a handoff package so another person can set up, verify, and maintain your workflow.\n\n## 2. Before you start\nYour workflow artifacts from Tasks 1–9, configuration, error handling, monitoring, and tests.\n\n## 3. Step-by-step work\n1. Continue your earlier automation project in your own repository/workflow file.\n2. Document setup, triggers, environment variables, and manual execution.\n3. Document the workflow diagram, data mapping, retries, and notifications.\n4. Include test results, metrics, limitations, and failure recovery.\n5. Remove secrets and verify the setup instructions in a clean environment.\n6. Prioritize the next three improvements.\n\n## 4. Concrete example and explanation\nSet up in a new folder, send the sample event, and compare the expected output. Explain which log to inspect after failure and how to retry safely.\n\n## 5. What to submit\nYour own GitHub repository/workflow export, README, diagram, test/metrics report, and next steps. Another person must be able to recreate the workflow from the instructions.\n\n## 6. How to check your work\nReproduce clean setup plus success/failure paths. Configuration examples contain no real keys; include measurements and three prioritized next steps."}]$legacy_payload$::jsonb);
DO $preflight$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE i.slug='automation-engineering' AND t.title=e.item->>'title'
 AND t.instructions=e.item->>'old_instructions' AND t.description=e.item->>'old_description'
 AND t.status='published' AND t.is_required;
 IF (SELECT jsonb_array_length(payload) FROM legacy_guides)<>10 OR n<>10 THEN RAISE EXCEPTION 'Version mismatch in automation-engineering: %',n; END IF;
END; $preflight$;
DO $apply$
DECLARE n integer;
BEGIN
 UPDATE public.internship_tasks t SET instructions=e.item->>'new_instructions',description=e.item->>'new_description'
 FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 WHERE i.slug='automation-engineering' AND t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 AND t.title=e.item->>'title' AND t.instructions=e.item->>'old_instructions' AND t.description=e.item->>'old_description';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>10 THEN RAISE EXCEPTION 'Expected 10 changed tasks for automation-engineering, got %',n; END IF;
END; $apply$;
DO $verify$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE i.slug='automation-engineering' AND t.instructions=e.item->>'new_instructions' AND t.description=e.item->>'new_description'
 AND t.status='published' AND t.is_required;
 IF n<>10 THEN RAISE EXCEPTION 'Postcheck mismatch in automation-engineering: %',n; END IF;
END; $verify$;
COMMIT;
